(()=>{'use strict';
class FormulaError extends Error{constructor(code){super(code);this.code=code;}}
const fail=code=>{throw new FormulaError(code);};
function address(text){const m=/^\$?([A-Z]+)\$?([1-9]\d*)$/i.exec(text);if(!m)fail('#REF!');let col=0;for(const c of m[1].toUpperCase())col=col*26+c.charCodeAt(0)-64;return{row:Number(m[2])-1,col:col-1};}
function caption(row,col){let n=col+1,s='';while(n){s=String.fromCharCode(65+(n-1)%26)+s;n=Math.floor((n-1)/26);}return s+(row+1);}
function tokenize(text){if(text.length>2000)fail('#LIMIT!');let i=0;const out=[];while(i<text.length){if(/\s/.test(text[i])){i++;continue;}const start=i,c=text[i];if(c==='"'||c==="'"){let value='';i++;let closed=false;while(i<text.length){if(text[i]===c){if(text[i+1]===c){value+=c;i+=2;}else{i++;closed=true;break;}}else value+=text[i++];}if(!closed)fail('#VALUE!');out.push({kind:c==='"'?'string':'id',value,start,end:i});}else{const tail=text.slice(i),number=/^(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?/i.exec(tail),id=/^(?:\$?[A-Za-z]+\$?[1-9]\d*|[\p{L}_][\p{L}\p{N}_.]*)/u.exec(tail),op=/^(?:<=|>=|<>|[+\-*/^(),:!<>=])/.exec(tail);if(number){i+=number[0].length;out.push({kind:'number',value:Number(number[0]),start,end:i});}else if(id){i+=id[0].length;out.push({kind:'id',value:id[0],start,end:i});}else if(op){i+=op[0].length;out.push({kind:op[0],value:op[0],start,end:i});}else fail('#VALUE!');}if(out.length>512)fail('#LIMIT!');}out.push({kind:'end',start:i,end:i});return out;}
function parse(text){const tokens=tokenize(text);let at=0,depth=0;const peek=()=>tokens[at],take=kind=>{if(peek().kind!==kind)fail('#VALUE!');return tokens[at++];};function expression(level=0){if(++depth>80)fail('#LIMIT!');const levels=[['=','<>','<','>','<=','>='],['+','-'],['*','/'],['^']];let node;if(level<levels.length){node=expression(level+1);while(levels[level].includes(peek().kind)){const op=tokens[at++].kind,right=expression(level+(op==='^'?0:1));node={type:'binary',op,left:node,right};}}else if(['+','-'].includes(peek().kind)){const op=tokens[at++].kind;node={type:'unary',op,value:expression(level)};}else if(peek().kind==='('){take('(');node=expression();take(')');}else if(peek().kind==='number'||peek().kind==='string'){const t=tokens[at++];node={type:'value',value:t.value};}else if(peek().kind==='id'){const id=take('id').value;if(peek().kind==='('){take('(');const args=[];if(peek().kind!==')'){args.push(expression());while(peek().kind===','){take(',');args.push(expression());}}take(')');node={type:'call',name:id.toUpperCase(),args};}else if(['TRUE','FALSE'].includes(id.toUpperCase())&&peek().kind!=='!')node={type:'value',value:id.toUpperCase()==='TRUE'};else{let sheet=null,from=id;if(peek().kind==='!'){take('!');sheet=id;from=take('id').value;}address(from);let to=null;if(peek().kind===':'){take(':');to=take('id').value;address(to);}node={type:'ref',sheet,from,to};}}else fail('#VALUE!');depth--;return node;}const tree=expression();if(peek().kind!=='end')fail('#VALUE!');return tree;}
const number=value=>{if(Array.isArray(value))fail('#VALUE!');if(value===''||value===null)return 0;if(typeof value==='boolean')return Number(value);if(typeof value==='number'&&Number.isFinite(value))return value;if(typeof value==='string'&&value.trim()!==''&&Number.isFinite(Number(value)))return Number(value);fail('#VALUE!');};
function engine(sheets){const memo=new Map(),syntax=new Map();let budget=20000;function calc(sheetId,cell,trail=new Set()){if(--budget<0||trail.size>100)fail('#LIMIT!');const sheet=sheets.find(s=>s.id===sheetId);if(!sheet)fail('#REF!');const pos=address(cell);if(pos.row>=sheet.rows||pos.col>=sheet.cols)fail('#REF!');const key=sheet.id+'!'+caption(pos.row,pos.col);if(trail.has(key))fail('#CYCLE!');if(memo.has(key))return memo.get(key);const raw=String(sheet.cells[caption(pos.row,pos.col)]?.raw??'');let value;if(raw.trim().startsWith('=')){const formula=raw.trim().slice(1);let ast=syntax.get(formula);if(!ast){ast=parse(formula);syntax.set(formula,ast);}const next=new Set(trail);next.add(key);value=evaluate(ast,sheet,next);}else value=raw.trim()!==''&&Number.isFinite(Number(raw))?Number(raw):raw;if(typeof value==='number'&&!Number.isFinite(value))fail('#NUM!');memo.set(key,value);return value;}
function evaluate(node,sheet,trail){if(--budget<0)fail('#LIMIT!');if(node.type==='value')return node.value;if(node.type==='unary'){const v=number(evaluate(node.value,sheet,trail));return node.op==='-'?-v:v;}if(node.type==='ref'){const target=node.sheet?sheets.find(s=>s.name===node.sheet):sheet;if(!target)fail('#REF!');if(!node.to)return calc(target.id,node.from,trail);const a=address(node.from),b=address(node.to);if(a.row>b.row||a.col>b.col||b.row>=target.rows||b.col>=target.cols)fail('#REF!');if((b.row-a.row+1)*(b.col-a.col+1)>4000)fail('#LIMIT!');const out=[];for(let row=a.row;row<=b.row;row++)for(let col=a.col;col<=b.col;col++)out.push(calc(target.id,caption(row,col),trail));return out;}if(node.type==='binary'){const left=evaluate(node.left,sheet,trail),right=evaluate(node.right,sheet,trail);if(['=','<>'].includes(node.op))return node.op==='='?left===right:left!==right;const a=number(left),b=number(right);if(node.op==='<')return a<b;if(node.op==='>')return a>b;if(node.op==='<=')return a<=b;if(node.op==='>=')return a>=b;if(node.op==='+')return a+b;if(node.op==='-')return a-b;if(node.op==='*')return a*b;if(node.op==='/'){if(b===0)fail('#DIV/0!');return a/b;}return a**b;}if(node.type==='call'){const n=node.name,args=node.args;if(n==='IF'){if(args.length!==3)fail('#VALUE!');return evaluate(number(evaluate(args[0],sheet,trail))!==0?args[1]:args[2],sheet,trail);}if(n==='IFERROR'){if(args.length!==2)fail('#VALUE!');try{return evaluate(args[0],sheet,trail);}catch(e){if(!(e instanceof FormulaError))throw e;return evaluate(args[1],sheet,trail);}}const values=args.flatMap(a=>{const v=evaluate(a,sheet,trail);return Array.isArray(v)?v:[v];});if(n==='ROUND'){if(values.length!==2)fail('#VALUE!');const precision=number(values[1]);if(!Number.isInteger(precision)||Math.abs(precision)>10)fail('#NUM!');const m=10**precision;return Math.round((number(values[0])+Number.EPSILON)*m)/m;}if(n==='COUNT')return values.filter(v=>typeof v==='number'&&Number.isFinite(v)).length;if(!['SUM','MIN','MAX','AVERAGE','ABS'].includes(n))fail('#NAME?');const nums=values.map(number);if(n==='ABS'){if(nums.length!==1)fail('#VALUE!');return Math.abs(nums[0]);}if(!nums.length){if(n==='SUM')return 0;fail('#DIV/0!');}if(n==='SUM')return nums.reduce((a,b)=>a+b,0);if(n==='MIN')return Math.min(...nums);if(n==='MAX')return Math.max(...nums);return nums.reduce((a,b)=>a+b,0)/nums.length;}fail('#VALUE!');}
return{value(sheetId,cell){try{const value=calc(sheetId,cell);if(typeof value==='number'&&!Number.isFinite(value))fail('#NUM!');return{value,error:null};}catch(e){if(!(e instanceof FormulaError))throw e;return{value:e.code,error:e.code};}},resetBudget(){budget=20000;}};}
function rename(raw,oldName,newName){if(!String(raw).trim().startsWith('='))return raw;const t=tokenize(raw.slice(1)),changes=[];for(let i=0;i<t.length-1;i++)if(t[i].kind==='id'&&t[i].value===oldName&&t[i+1].kind==='!')changes.push(t[i]);let result=raw;for(const token of changes.reverse())result=result.slice(0,token.start+1)+"'"+newName.replace(/'/g,"''")+"'"+result.slice(token.end+1);return result;}
window.ENHANCED_FORMULAS={engine,address,caption,rename,parse};
})();
